const event = $input.item.json;

// Normalize event type for broadcast
const broadcastPacket = {
  event_type: event.event || 'DATA_UPDATE',
  race_id: event.race_id || event.data?.[0]?.race_id,
  timestamp: new Date().toISOString(),
  payload: event.data || event,
  // Leaderboard sorted by composite score
  leaderboard: (event.data || []).sort((a, b) => (b.scores?.composite || 0) - (a.scores?.composite || 0)).slice(0, 6).map((v, i) => ({
    rank: i + 1,
    vehicle_id: v.vehicle_id,
    composite: v.scores?.composite,
    battery_pct: v.battery_pct
  }))
};

return [{ json: broadcastPacket }];
